                            new_routes.append(routes[t])
                    d = total_cost(new_routes) - base_total
                    cand = (d, worst_i, pos, j, 0, new_routes)
                    if best_move is None or d < best_move[0] or (
                        d == best_move[0] and (worst_i, pos, j, 0) < (best_move[1], best_move[2], best_move[3], best_move[4])
                    ):
                        best_move = cand
                    continue

                load_to = loads[j]
                if load_to + demands[cust] > cap:
                    continue
                for ins in range(0, len(r_to) + 1):
                    new_to = r_to[:ins] + [cust] + r_to[ins:]
                    if demands[cust] + load_to > cap:
                        continue
                    new_routes = []
                    for t in range(len(routes)):
                        if t == worst_i:
                            new_routes.append(rem_route)
                        elif t == j:
                            new_routes.append(new_to)
                        else:
                            new_routes.append(routes[t])
                    d = total_cost(new_routes) - base_total
                    if best_move is None or d < best_move[0] or (
                        d == best_move[0] and (worst_i, pos, j, ins) < (best_move[1], best_move[2], best_move[3], best_move[4])
                    ):
                        best_move = (d, worst_i, pos, j, ins, new_routes)

        if best_move is None:
            return False
        if best_move[0] < 0:
            routes[:] = best_move[5]
            routes[:] = [r for r in routes if r]
            return True
        return False

    # --- Construct initial solution (small edit: deterministic Clarke-Wright savings) ---
    # Start with singleton routes (feasible), then merge end-to-start when capacity allows.
    routes = [[c] for c in sorted(customers)]
    n0 = len(routes)
    if n0 == 0:
        return []

    # customer -> route index
    cust_route = {}
    for idx, r in enumerate(routes):
        cust_route[r[0]] = idx

    # deterministic savings list
    clist = sorted(customers)
    savings = []
    for a_i in range(len(clist)):
        i = clist[a_i]
        di = demands[i]
        for a_j in range(a_i + 1, len(clist)):
            j = clist[a_j]
            # savings = d0i + d0j - dij
            s = matrix[depot][i] + matrix[depot][j] - matrix[i][j]
            savings.append((s, i, j))
    # sort descending by savings then deterministic by (i,j)
    savings.sort(key=lambda x: (-x[0], x[1], x[2]))

    # helper to rebuild cust_route after merges for safety (cheap since edits are few)
    def rebuild_map():
        for k in list(cust_route.keys()):
            pass
        cust_route.clear()
        for idx, r in enumerate(routes):
            for v in r:
                cust_route[v] = idx

    # attempt merges; keep doing until target route count or no more merges
    merged_any = True
    iter_guard = 0
    while merged_any and len(routes) > 1 and iter_guard < 5000:
        iter_guard += 1
        merged_any = False
        rebuild_map()
        # route endpoint checks only
        for _, i, j in savings:
            if i not in cust_route or j not in cust_route:
                continue
            ri = cust_route[i]
            rj = cust_route[j]
            if ri == rj:
                continue
            r1 = routes[ri]
            r2 = routes[rj]
            if not r1 or not r2:
                continue
            load1 = route_load(r1)
            load2 = route_load(r2)
            if load1 + load2 > capacity:
                continue

            # i must be at one end of r1, j at the corresponding other end of r2
            i_left = (r1[0] == i)
            i_right = (r1[-1] == i)
            j_left = (r2[0] == j)
            j_right = (r2[-1] == j)

            # Consider four orientation cases that create a merged route with i-j adjacency.
            # Merged patterns:
            # 1) r1 + r2  if i is right end and j is left end
            # 2) r1 + rev(r2) if i is right end and j is right end
            # 3) rev(r1) + r2 if i is left end and j is left end
            # 4) rev(r1) + rev(r2) if i is left end and j is right end
            merged = None
            if i_right and j_left:
                merged = r1 + r2
            elif i_right and j_right:
                merged = r1 + r2[::-1]
            elif i_left and j_left:
                merged = r1[::-1] + r2
            elif i_left and j_right:
                merged = r1[::-1] + r2[::-1]

            if merged is None:
                continue

            # accept merge if it does not make it worse too much; deterministic small guidance
            base = route_cost(r1) + route_cost(r2)
            newc = route_cost(merged)
            delta = newc - base
            # allow slightly non-improving merges early to reduce fragmentation
            allow_non_improve = len(routes) > target_routes
            if delta < 0 or (allow_non_improve and delta <= max(0, int(0.002 * base))):
                # remove higher index first
                if ri < rj:
                    routes.pop(rj)
                    routes.pop(ri)
                    routes.append(merged)
                else:
                    routes.pop(ri)
                    routes.pop(rj)
                    routes.append(merged)
                merged_any = True
                break

        # stop when close to target
        if len(routes) <= target_routes:
            break

    routes = [r for r in routes if r]

    # --- Improvements: merges + 2-opt + relocate ---
    improved = True
    merge_rounds = 0
    while improved and merge_rounds < 30:
        merge_rounds += 1
        m = best_merge_pair(routes, capacity)
        if m is None:
            break
        i, j, new_r, delta = m

        base_total = total_cost(routes)
        allow_non_improve = (len(routes) > target_routes)
        if delta <= 0 or (allow_non_improve and delta <= max(0, int(0.0015 * base_total))):
            if i < j:
                routes.pop(j)
                routes.pop(i)
            else:
                routes.pop(i)
                routes.pop(j)
            routes.append(new_r)
            routes[:] = [r for r in routes if r]
        else:
            break

    for idx in range(len(routes)):
        r = routes[idx]
        new_r, d = two_opt_best(r, capacity)
        if d < 0:
            routes[idx] = new_r

    relocate_rounds = 0
